-- 019_sales_orders.sql: customer orders linked to the existing stock request and approval flow.
begin;
create table if not exists public.sal_customers(
 id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id),name text not null check(length(trim(name)) between 1 and 200),contact text,city text,phone text,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(org_id,id));
create unique index if not exists sal_customers_org_name_active_uq on public.sal_customers(org_id,lower(name)) where deleted_at is null;
create table if not exists public.sal_orders(
 id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id),number text not null,customer_id uuid not null,warehouse_id uuid not null,
 status text not null default 'open' check(status in ('open','stock_requested','cancelled')),currency char(3) not null check(currency ~ '^[A-Z]{3}$'),request_id uuid,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,
 unique(org_id,id),unique(org_id,number),foreign key(org_id,customer_id) references public.sal_customers(org_id,id),foreign key(org_id,warehouse_id) references public.inv_warehouses(org_id,id),foreign key(org_id,request_id) references public.inv_requests(org_id,id));
create table if not exists public.sal_order_lines(
 id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations(id),order_id uuid not null,item_id uuid not null,qty numeric(18,3) not null check(qty>0),unit_price_minor bigint not null check(unit_price_minor>=0),
 created_at timestamptz not null default now(),unique(org_id,id),unique(order_id,item_id),foreign key(org_id,order_id) references public.sal_orders(org_id,id),foreign key(org_id,item_id) references public.inv_items(org_id,id));
create index if not exists sal_orders_org_status_idx on public.sal_orders(org_id,status,created_at desc);
create index if not exists sal_lines_org_order_idx on public.sal_order_lines(org_id,order_id);
drop trigger if exists sal_customers_updated_at on public.sal_customers;create trigger sal_customers_updated_at before update on public.sal_customers for each row execute function public.set_updated_at();
drop trigger if exists sal_orders_updated_at on public.sal_orders;create trigger sal_orders_updated_at before update on public.sal_orders for each row execute function public.set_updated_at();
alter table public.sal_customers enable row level security;alter table public.sal_orders enable row level security;alter table public.sal_order_lines enable row level security;
revoke all on public.sal_customers,public.sal_orders,public.sal_order_lines from anon,authenticated;grant select on public.sal_customers,public.sal_orders,public.sal_order_lines to authenticated;
drop policy if exists sal_customers_member_read on public.sal_customers;create policy sal_customers_member_read on public.sal_customers for select to authenticated using(public.is_org_member(org_id));
drop policy if exists sal_orders_member_read on public.sal_orders;create policy sal_orders_member_read on public.sal_orders for select to authenticated using(public.is_org_member(org_id));
drop policy if exists sal_lines_member_read on public.sal_order_lines;create policy sal_lines_member_read on public.sal_order_lines for select to authenticated using(public.is_org_member(org_id));

create or replace function public.sal__guard(p_roles text[]) returns uuid language plpgsql security definer set search_path=public as $$ declare v uuid:=public.require_org_role(p_roles);begin if not exists(select 1 from public.org_modules where org_id=v and module_key='sales' and disabled_at is null) then raise exception 'MODULE_DISABLED';end if;return v;end; $$;
create or replace function public.sal__next_number(p_org uuid) returns text language plpgsql security definer set search_path=public as $$ declare v bigint;begin insert into public.inv_counters(org_id,key,value) values(p_org,'sales_order',1) on conflict(org_id,key) do update set value=public.inv_counters.value+1 returning value into v;return 'SO-'||lpad(v::text,4,'0');end; $$;
create or replace function public.sal_create_customer(p_name text,p_contact text default null,p_city text default null,p_phone text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_org uuid:=public.sal__guard(array['owner','admin']);v_id uuid;begin if length(trim(coalesce(p_name,'')))=0 then raise exception 'INVALID_INPUT';end if;insert into public.sal_customers(org_id,name,contact,city,phone) values(v_org,trim(p_name),nullif(trim(p_contact),''),nullif(trim(p_city),''),nullif(trim(p_phone),'')) returning id into v_id;insert into public.audit_log(org_id,actor_user_id,action,entity_type,entity_id,summary) values(v_org,auth.uid(),'sales.customer.created','customer',v_id::text,trim(p_name));return v_id;end; $$;
create or replace function public.sal_create_order(p_customer_id uuid,p_warehouse_id uuid,p_lines jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_org uuid:=public.sal__guard(array['owner','admin','member']);v_id uuid;v_no text;v_currency char(3);e jsonb;v_item uuid;v_qty numeric;v_price bigint;v_count int:=0;begin if not exists(select 1 from public.sal_customers where org_id=v_org and id=p_customer_id and deleted_at is null) or not exists(select 1 from public.inv_warehouses where org_id=v_org and id=p_warehouse_id and deleted_at is null) then raise exception 'NOT_FOUND';end if;if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'INVALID_INPUT';end if;select default_currency into v_currency from public.organizations where id=v_org;v_no:=public.sal__next_number(v_org);insert into public.sal_orders(org_id,number,customer_id,warehouse_id,currency,created_by) values(v_org,v_no,p_customer_id,p_warehouse_id,v_currency,auth.uid()) returning id into v_id;for e in select value from jsonb_array_elements(p_lines) loop begin v_item:=(e->>'itemId')::uuid;v_qty:=(e->>'qty')::numeric;v_price:=(e->>'unitPriceMinor')::bigint;exception when others then raise exception 'INVALID_INPUT';end;if v_qty<=0 or v_price<0 or not exists(select 1 from public.inv_items where org_id=v_org and id=v_item and deleted_at is null) then raise exception 'INVALID_INPUT';end;insert into public.sal_order_lines(org_id,order_id,item_id,qty,unit_price_minor) values(v_org,v_id,v_item,v_qty,v_price);v_count:=v_count+1;end loop;insert into public.audit_log(org_id,actor_user_id,action,entity_type,entity_id,summary) values(v_org,auth.uid(),'sales.order.created','sales_order',v_id::text,format('%s created with %s line(s)',v_no,v_count));return jsonb_build_object('id',v_id,'number',v_no);end; $$;
create or replace function public.sal_request_stock(p_order_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_org uuid:=public.sal__guard(array['owner','admin','member']);o public.sal_orders%rowtype;v_req jsonb;begin select * into o from public.sal_orders where org_id=v_org and id=p_order_id and deleted_at is null for update;if not found then raise exception 'NOT_FOUND';end if;if o.status not in ('open') then raise exception 'INVALID_STATE';end if;select public.inv_submit_request(o.warehouse_id,format('Sales order %s',o.number),coalesce(jsonb_agg(jsonb_build_object('itemId',item_id,'qty',qty) order by item_id),'[]'::jsonb)) into v_req from public.sal_order_lines where org_id=v_org and order_id=o.id;update public.sal_orders set status='stock_requested',request_id=(v_req->>'id')::uuid where id=o.id;insert into public.audit_log(org_id,actor_user_id,action,entity_type,entity_id,summary) values(v_org,auth.uid(),'sales.order.stock_requested','sales_order',o.id::text,format('%s linked to request %s',o.number,v_req->>'number'));return v_req;end; $$;
create or replace function public.sal_cancel_order(p_order_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v_org uuid:=public.sal__guard(array['owner','admin','member']);o public.sal_orders%rowtype;begin select * into o from public.sal_orders where org_id=v_org and id=p_order_id and deleted_at is null for update;if not found then raise exception 'NOT_FOUND';end if;if o.status='cancelled' then raise exception 'INVALID_STATE';end if;if o.request_id is not null then perform public.inv_cancel_request(o.request_id);end if;update public.sal_orders set status='cancelled' where id=o.id;insert into public.audit_log(org_id,actor_user_id,action,entity_type,entity_id,summary) values(v_org,auth.uid(),'sales.order.cancelled','sales_order',o.id::text,format('%s cancelled',o.number));end; $$;
revoke all on function public.sal__guard(text[]),public.sal__next_number(uuid) from public,anon,authenticated;
revoke all on function public.sal_create_customer(text,text,text,text),public.sal_create_order(uuid,uuid,jsonb),public.sal_request_stock(uuid),public.sal_cancel_order(uuid) from public,anon;
grant execute on function public.sal_create_customer(text,text,text,text),public.sal_create_order(uuid,uuid,jsonb),public.sal_request_stock(uuid),public.sal_cancel_order(uuid) to authenticated;
commit;
select relname from pg_class where relnamespace='public'::regnamespace and relname in('sal_customers','sal_orders','sal_order_lines') and relrowsecurity order by relname;
